import com.google.gson.Gson;
import com.google.gson.GsonBuilder;

public class Demo {
  public static void main(String[] args) {
    Gson gson = new GsonBuilder().setDateFormat("yyyy-MM-dd").create();
    Person p = new Person();
    System.out.println("null field: " + gson.toJson(p));
    p.setAge(new java.util.Date(0));
    System.out.println("non-null:   " + gson.toJson(p));
    Person q = gson.fromJson("{\"age\":null}", Person.class);
